@pytest.mark.unit
class TestComponentStateMachine(RuleBasedStateMachine):
    """Stateful testing for component lifecycle management."""
    
    def __init__(self):
        super().__init__()
        self.component = None
        self.component_name = None
        self.state_history: List[Dict] = []
    
    @rule(component_name=st.sampled_from([c["name"] for c in load_components()["components"]]))
    def initialize_component(self, component_name: str):
        """Initialize a component instance."""
        module = pytest.importorskip(f"src.components.{component_name}")
        self.component = module.create_instance()
        self.component_name = component_name
        self.state_history = []
    
    @precondition(lambda self: self.component is not None)
    @rule(data=st.dictionaries(st.text(), st.integers()))
    def process_data(self, data: Dict[str, int]):
        """Process data through the component."""
        try:
            result = self.component.process(data)
            self.state_history.append({"action": "process", "data": data, "result": result})
        except Exception as e:
            self.state_history.append({"action": "process_error", "data": data, "error": str(e)})
    
    @precondition(lambda self: self.component is not None)
    @rule()
    def reset_component(self):
        """Reset the component to initial state."""
        self.component.reset()
        self.state_history.append({"action": "reset"})
    
    @precondition(lambda self: self.component is not None)
    @rule()
    def validate_state(self):
        """Validate component state consistency."""
        state = self.component.get_full_state()
        assert isinstance(state, dict), "State must be a dictionary"
        self.state_history.append({"action": "validate", "state": state})
    
    @invariant()
    def state_history_consistency(self):
        """Ensure state history maintains consistency."""
        if self.component is not None:
            assert isinstance(self.state_history, list)
            assert len(self.state_history) < 1000  # Prevent unbounded growth


