@pytest.mark.slow
class TestComponentStress:
    """Stress tests for component resilience under heavy load."""

    @pytest.mark.parametrize("component_name", [
        c["name"] for c in load_components()["components"]
    ])
    def test_continuous_processing_stress(self, component_name: str):
        """Run continuous processing for extended period to detect memory leaks."""
        module = pytest.importorskip(f"src.components.{component_name}")
        instance = module.create_instance()
        
        # Baseline memory
        gc.collect()
        baseline_memory = psutil.Process().memory_info().rss / 1024 / 1024
        
        # Stress loop
        for i in range(STRESS_ITERATIONS):
            input_data = {
                "iteration": i,
                "data": [random.randint(0, 1000) for _ in range(100)],
                "timestamp": time.time()
            }
            try:
                result = instance.process(input_data)
                assert result is not None
            except Exception as e:
                pytest.fail(f"Stress iteration {i} failed: {e}")
            
            # Periodic memory check
            if i % 100 == 0:
                gc.collect()
                current_memory = psutil.Process().memory_info().rss / 1024 / 1024
                memory_growth = current_memory - baseline_memory
                assert memory_growth < MEMORY_LEAK_THRESHOLD_MB, \
                    f"Memory leak detected at iteration {i}: {memory_growth:.2f}MB"
        
        logger.info(f"Completed {STRESS_ITERATIONS} stress iterations for {component_name}")

    @pytest.mark.parametrize("component_name", [
        c["name"] for c in load_components()["components"]
    ])
    def test_concurrent_processing(self, component_name: str):
        """Test component thread-safety under concurrent access."""
        module = pytest.importorskip(f"src.components.{component_name}")
        
        def worker(worker_id: int, results: List):
            """Worker function for concurrent processing."""
            instance = module.create_instance()
            for i in range(100):
                input_data = {
                    "worker": worker_id,
                    "iteration": i,
                    "data": f"test_data_{worker_id}_{i}"
                }
                try:
                    result = instance.process(input_data)
                    results.append(result)
                except Exception as e:
                    results.append(f"ERROR: {e}")
        
        results = []
        with ThreadPoolExecutor(max_workers=CONCURRENCY_LEVEL) as executor:
            futures = [executor.submit(worker, i, results) for i in range(CONCURRENCY_LEVEL)]
            for future in futures:
                future.result(timeout=30)
        
        # Verify no errors occurred
        errors = [r for r in results if isinstance(r, str) and r.startswith("ERROR")]
        assert len(errors) == 0, f"Concurrent processing errors: {errors[:5]}"
        logger.info(f"Concurrent processing completed: {len(results)} results")

    @pytest.mark.parametrize("component_name", [
        c["name"] for c in load_components()["components"]
    ])
    def test_error_recovery(self, component_name: str):
        """Test component recovery after error conditions."""
        module = pytest.importorskip(f"src.components.{component_name}")
        instance = module.create_instance()
        
        # Inject various error conditions
        error_inputs = [
            None,
            {},
            {"invalid": object()},  # Non-serializable
            {"data": [1, 2, 3], "operation": "invalid_op"},
            {"data": "x" * 10000},  # Large input
            {"data": {"nested": {"deep": {"structure": "test"}}}},
        ]
        
        for i, error_input in enumerate(error_inputs):
            try:
                instance.process(error_input)
            except Exception:
                pass  # Expected error
            
            # Verify component still functional
