        start_time = time.time()
        operations = 1000
        for i in range(operations):
            instance.process({"iteration": i})
        elapsed = time.time() - start_time
        
        throughput = operations / elapsed
        logger.info(f"{component_name} throughput: {throughput:.2f} ops/sec")
        
        # Minimum throughput threshold (adjust based on component complexity)
        assert throughput > 10, f"Throughput too low: {throughput:.2f} ops/sec"

