@pytest.mark.chaos
class TestComponentChaos:
    """Chaos engineering tests for component resilience."""

    @pytest.mark.parametrize("component_name", [
        c["name"] for c in load_components()["components"]
    ])
    def test_random_fault_injection(self, component_name: str):
        """Inject random faults and verify graceful degradation."""
        module = pytest.importorskip(f"src.components.{component_name}")
        instance = module.create_instance()
        
        # Fault injection scenarios
        fault_scenarios = [
            lambda: instance.process(None),
            lambda: instance.process({}),
            lambda: instance.process({"data": None}),
            lambda: instance.process({"data": []}),
            lambda: instance.process({"data": {}}),
            lambda: instance.process({"data": "invalid"}),
            lambda: instance.process({"data": 123}),
            lambda: instance.process({"data": True}),
            lambda: instance.process({"data": [None, None, None]}),
            lambda: instance.process({"data": {"nested": None}}),
        ]
        
        for i, fault in enumerate(fault_scenarios):
            try:
                fault()
            except Exception:
                pass  # Expected failure
            
            # Verify component still operational
            try:
                result = instance.process({"test": f"after_fault_{i}"})
                assert result is not None
            except Exception as e:
                pytest.fail(f"Component failed after fault {i}: {e}")

